import{_ as i,o as a,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const m=JSON.parse('{"title":"维护检查清单","description":"","frontmatter":{},"headers":[],"relativePath":"维护与报告/维护检查清单.md","filePath":"维护与报告/维护检查清单.md","lastUpdated":1776864657000}'),r={name:"维护与报告/维护检查清单.md"};function o(c,l,t,h,n,s){return a(),e("div",null,[...l[0]||(l[0]=[d('<h1 id="维护检查清单" tabindex="-1">维护检查清单 <a class="header-anchor" href="#维护检查清单" aria-label="Permalink to “维护检查清单”">​</a></h1><p>一句话摘要：这是一份把维护动作落到执行层的检查表，用来帮助维护者在补文、修链、补证和收尾时不漏关键步骤。</p><ul><li>适合对象：维护者、整理者、后续协作者</li><li>当前状态：已整理</li><li>可信度：<code>[已确认]</code></li><li>关联文档：<code>docs/维护与报告/维护流程说明.md</code>、<code>docs/维护与报告/文档状态分级规则.md</code>、<code>docs/错误点与优化点汇总.md</code></li></ul><h2 id="什么时候用这份清单" tabindex="-1">什么时候用这份清单 <a class="header-anchor" href="#什么时候用这份清单" aria-label="Permalink to “什么时候用这份清单”">​</a></h2><p>适合在下面几种场景使用：</p><ul><li>新增栏目页之后</li><li>扩写专题正文之后</li><li>补 OCR 回链之后</li><li>批量修路径、命名或状态之后</li><li>准备结束一轮维护之前</li></ul><h2 id="一、入口检查" tabindex="-1">一、入口检查 <a class="header-anchor" href="#一、入口检查" aria-label="Permalink to “一、入口检查”">​</a></h2><ul><li>[ ] 能否从 <code>docs/总索引与导航/创游世界知识库总导航.md</code> 找到</li><li>[ ] 能否从所属栏目页找到</li><li>[ ] 新增页面是否写入了关联阅读</li><li>[ ] 相关栏目页是否同步接入新页面</li></ul><h2 id="二、结构检查" tabindex="-1">二、结构检查 <a class="header-anchor" href="#二、结构检查" aria-label="Permalink to “二、结构检查”">​</a></h2><ul><li>[ ] 标题是否明确</li><li>[ ] 是否有一句话摘要</li><li>[ ] 是否标明适合对象</li><li>[ ] 是否标明当前状态</li><li>[ ] 是否标明可信度</li><li>[ ] 是否说明这页适合解决什么问题</li></ul><h2 id="三、内容检查" tabindex="-1">三、内容检查 <a class="header-anchor" href="#三、内容检查" aria-label="Permalink to “三、内容检查”">​</a></h2><ul><li>[ ] 是否区分“已确认 / 高可信推断 / 待验证”</li><li>[ ] 是否存在明显过时的待办描述</li><li>[ ] 是否说明推荐阅读顺序或使用顺序</li><li>[ ] 是否补了常见误区 / 适用边界 / 当前判断</li></ul><h2 id="四、证据与回链检查" tabindex="-1">四、证据与回链检查 <a class="header-anchor" href="#四、证据与回链检查" aria-label="Permalink to “四、证据与回链检查”">​</a></h2><ul><li>[ ] 高价值专题是否补了 OCR 回链</li><li>[ ] 是否能从专题反查到 OCR 文档或映射表</li><li>[ ] 是否存在需要补“来源截图编号 / 对应 OCR 文档 / 对应映射表”的位置</li><li>[ ] 是否把新证据同步到推进清单或状态总览</li></ul><h2 id="五、命名与一致性检查" tabindex="-1">五、命名与一致性检查 <a class="header-anchor" href="#五、命名与一致性检查" aria-label="Permalink to “五、命名与一致性检查”">​</a></h2><ul><li>[ ] 路径名称是否统一</li><li>[ ] 术语是否与术语表一致</li><li>[ ] 状态词是否与统一状态词执行标准一致</li><li>[ ] 同一类导航页的头部模板是否基本一致</li></ul><h2 id="六、收尾判断" tabindex="-1">六、收尾判断 <a class="header-anchor" href="#六、收尾判断" aria-label="Permalink to “六、收尾判断”">​</a></h2><p>满足下面大部分条件时，可认为这一轮维护基本完整：</p><ul><li>页面已接入导航</li><li>页面结构完整</li><li>关键结论带有可信度说明</li><li>高价值文档已有最小回链</li><li>相关治理页已同步更新</li></ul><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to “关联阅读”">​</a></h2><ul><li><code>docs/维护与报告/维护与报告导航.md</code></li><li><code>docs/维护与报告/维护流程说明.md</code></li><li><code>docs/维护与报告/文档状态分级规则.md</code></li></ul>',21)])])}const u=i(r,[["render",o]]);export{m as __pageData,u as default};
